@@ -331,0 +331,16 @@
+    /**
+     * Parse an ASCII hex digit that is part of a Unicode escape sequence. Does not advance character.
+     *
+     * @param ch    digit character
+     *
+     * @return value of digit if valid, else -1
+     */
+    private int unidigit(int ch) {
+        if (ch >= '0' && ch <= '9')
+            return ch - '0';
+        ch |= 0x20;
+        if (ch >= 'a' && ch <= 'f')
+            return 10 + ch - 'a';
+        return -1;
+    }
